import React from 'react';
import { NavLink } from 'react-router-dom';

export type NavItem = {
  id: string;
  label: string;
  path: string;
};

const defaultNavItems: NavItem[] = [
  { id: 'dashboard', label: 'Dashboard', path: '/dashboard' },
  { id: 'users',     label: 'Users',     path: '/users' },
  { id: 'auth',      label: 'Auth',      path: '/auth' },
];

interface NavbarProps {
  sidebarWidth?: number;
  navItems?: NavItem[];
  onToggleSidebar?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  sidebarWidth = 280,
  navItems = defaultNavItems,
  onToggleSidebar,
}) => {
  return (
    <header style={{
      position: 'fixed',
      top: 0,
      left: sidebarWidth,
      right: 0,
      height: 92,
      background: '#ffffff',
      borderBottom: '1px solid #E1E4EA',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: '10px 24px',
      boxSizing: 'border-box',
      zIndex: 99,
      transition: 'left 0.25s ease',
    }}>

      {/* Left: toggle + Nav links */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        {typeof onToggleSidebar === 'function' && (
          <button onClick={onToggleSidebar} aria-label="Toggle sidebar" style={{
            width: 36,
            height: 36,
            borderRadius: 8,
            border: 'none',
            background: 'transparent',
            cursor: 'pointer'
          }}>☰</button>
        )}

        <nav style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
        {navItems.map(item => (
          <NavLink
            key={item.id}
            to={item.path}
            style={({ isActive }) => ({
              textDecoration: 'none',
              fontSize: 14,
              fontWeight: isActive ? 600 : 400,
              color: isActive ? '#0b69ff' : '#4B5565',
              padding: '6px 14px',
              borderRadius: 8,
              background: isActive ? '#EFF4FF' : 'transparent',
              transition: 'background 0.15s ease, color 0.15s ease',
              whiteSpace: 'nowrap',
            })}
          >
            {item.label}
          </NavLink>
        ))}
      </nav>

    {/* Right: user avatar */}
    </div>
    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <div style={{
          width: 36,
          height: 36,
          borderRadius: '50%',
          background: '#E1E4EA',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: 14,
          color: '#4B5565',
          cursor: 'pointer',
          fontWeight: 600,
        }}>
          U
        </div>
      </div>
    </header>
  );
};

export default Navbar;
